window.docContents[184].resolve({"/Logic/#Sem___ntica-computacional-com-Lean--L___gica--L___gica-proposicional--Regras-de-dedu______o--Bi-implica______o":{"contents":"P ↔ Q é a conjunção das duas implicações, e as regras seguem disso:\nconstructor parte o objetivo nas duas direções, e .mp e .mpr são as\neliminações — de P para Q e de Q para P.\n\nexample : P ∧ Q ↔ Q ∧ P := by\n  constructor\n  · intro h; exact ⟨h.2, h.1⟩\n  · intro h; exact ⟨h.2, h.1⟩\n\nexample (h : P ↔ Q) (hP : P) : Q := h.mp hP\n\n\n","context":"Semântica computacional com Lean\u0009Lógica\u0009Lógica proposicional\u0009Regras de dedução","header":"5.1.2.5. Bi-implicação","id":"/Logic/#Sem___ntica-computacional-com-Lean--L___gica--L___gica-proposicional--Regras-de-dedu______o--Bi-implica______o"}});